import sys

def main():
    books = {}

    while True:
        try:
            line = input().strip()
            if not line:
                continue
            choice = int(line)

            if choice == 1:
                # Add a book
                book_id = int(input().strip())
                title = input().strip()
                books[book_id] = title
                print("Book added successfully.")

            elif choice == 2:
                # Search for a book by ID
                search_id = int(input().strip())
                if search_id in books:
                    print(f'Book found: ID={search_id}, Title="{books[search_id]}"')
                else:
                    print("Book not found.")

            elif choice == 3:
                # Delete a book by ID
                delete_id = int(input().strip())
                if delete_id in books:
                    del books[delete_id]
                    print("Book deleted successfully.")
                else:
                    print("Book ID not found.")

            elif choice == 4:
                # Display all books
                if not books:
                    print("No books in the library.")
                else:
                    for book_id, title in books.items():
                        print(f'Book ID={book_id}, Title="{title}"')

            elif choice == 5:
                # Exit
                print("Exiting the program...")
                break

        except EOFError:
            break
        except ValueError:
            continue

if __name__ == "__main__":
    main()
